/**
 * Locate the committed golden archives.
 *
 * These are generated by tools/rfa_golden_archives.py from bin/rfaPack.orig.exe and
 * committed. Calling the oracle from inside the test was tried first and abandoned: it
 * goes through cmd.exe, which rejects forward-slash paths and resolves relative paths
 * against its own working directory, so it failed for reasons that had nothing to do
 * with the writer.
 */
std::string golden_root()
{
	std::vector<std::string> candidates;

	if( const char * from_env = std::getenv( "RFA_TEST_DATA_DIR" ) ) {
		if( *from_env ) {
			candidates.push_back( std::string( from_env ) + "/golden" );
		}
	}

	candidates.push_back( "tests/data/golden" );
	candidates.push_back( "../tests/data/golden" );
	candidates.push_back( "../../tests/data/golden" );

	for( const std::string & candidate : candidates ) {
		if( std::filesystem::exists( std::filesystem::path( candidate ) ) ) {
			return candidate;
		}
	}

	return std::string();
}

/// Reports the first differing byte, because "31 bytes vs 31 bytes" is not a diagnosis.
void report_difference( const std::string & label,
                        const std::vector<unsigned char> & got,
                        const std::vector<unsigned char> & expected )
{
	const std::size_t limit = std::min( got.size(), expected.size() );
	std::size_t first = limit;

	for( std::size_t i = 0; i < limit; ++i ) {
		if( got[i] != expected[i] ) {
			first = i;
			break;
		}
	}

	std::cout << "[rfa] " << label << ": got " << got.size() << " bytes, expected "
	          << expected.size() << ", first difference at " << first << "\n";

	const std::size_t from = first > 8 ? first - 8 : 0;

	std::cout << "        got      :";
	for( std::size_t i = from; i < std::min( first + 8, got.size() ); ++i ) {
		std::printf( " %02X", got[i] );
	}
	std::cout << "\n        expected :";
	for( std::size_t i = from; i < std::min( first + 8, expected.size() ); ++i ) {
		std::printf( " %02X", expected[i] );
	}
	std::cout << "\n";
}

/// A scratch directory that cleans itself up, derived from a testcase scratch file name.
class Scratch
{
public:
	explicit Scratch( const std::string & seed )
	: root_( seed + ".work" )
	{
		std::error_code ec;
		std::filesystem::remove_all( root_, ec );
		std::filesystem::create_directories( root_, ec );
	}

	~Scratch()
	{
		std::error_code ec;
		std::filesystem::remove_all( root_, ec );
	}

	Scratch( const Scratch & ) = delete;
	Scratch & operator=( const Scratch & ) = delete;

	const std::string & root() const { return root_; }

	std::string path( const std::string & relative ) const
	{
		return ( std::filesystem::path( root_ ) / relative ).string();
	}

	void write( const std::string & relative, const std::vector<unsigned char> & data ) const
	{
		const std::filesystem::path full = std::filesystem::path( root_ ) / relative;

		std::error_code ec;
		std::filesystem::create_directories( full.parent_path(), ec );

		std::ofstream out( full.string().c_str(), std::ios::binary );
		out.write( (const char *)data.data(), (std::streamsize)data.size() );
	}

private:
	std::string root_;
};

std::vector<unsigned char> bytes( const std::string & text )
{
	return std::vector<unsigned char>( text.begin(), text.end() );
}

/// Deterministic pseudo-random data, so tests do not depend on <random> behaviour.
std::vector<unsigned char> pseudo_random( std::size_t size, std::uint32_t seed )
{
	std::vector<unsigned char> data;
	data.reserve( size );

	std::uint32_t state = seed;
	for( std::size_t i = 0; i < size; ++i ) {
		state = state * 1664525u + 1013904223u;
		data.push_back( (unsigned char)( state >> 24 ) );
	}

	return data;
}

std::vector<unsigned char> read_whole_file( const std::string & path )
{
	std::vector<unsigned char> data;

	std::ifstream file( path.c_str(), std::ios::binary );
	if( !file ) {
		return data;
	}

	char buffer[8192];
	for( ;; ) {
		file.read( buffer, sizeof( buffer ) );
		const std::streamsize got = file.gcount();
		if( got <= 0 ) {
			break;
		}
		data.insert( data.end(), buffer, buffer + got );
	}

	return data;
}

/// Writes a small tree under <scratch>/<name> and returns the directory holding it.
std::string make_tree( const Scratch & scratch, const std::string & name )
{
	const std::string root = scratch.path( name );

	scratch.write( name + "/a.txt", bytes( "Game.setNumberOfTickets 1 115\r\n" ) );
	scratch.write( name + "/empty.txt", std::vector<unsigned char>() );
	scratch.write( name + "/nested/deep.txt", bytes( "deep file contents\r\n" ) );
	scratch.write( name + "/blob.bin", pseudo_random( 204800, 4242 ) );   // 6.25 chunks

	return root;
}

bool build( const std::string & root,
            const std::string & base,
            const std::string & archive,
            CompressionPolicy policy,
            unsigned threads,
            std::string * error )
{
	std::vector<SourceFile> files;

	if( !RfaWriter::collect_files( root, base, files, error ) ) {
		return false;
	}

	WriteOptions options;
	options.policy = policy;
	options.threads = threads;

	RfaWriter writer;
	return writer.write( files, archive, options, nullptr, error );
}

/**
 * Byte-compares two archives, reporting where they diverge.
 *
 * Returns true only for an exact match - that is the whole point of the oracle test.
 */
bool compare_archives( const std::string & ours, const std::string & theirs, const std::string & label )
{
	const std::vector<unsigned char> a = read_whole_file( ours );
	const std::vector<unsigned char> b = read_whole_file( theirs );

	if( a.size() != b.size() ) {
		std::cout << "[rfa] " << label << ": size differs, ours=" << a.size()
		          << " oracle=" << b.size() << "\n";
	}

	const std::size_t limit = std::min( a.size(), b.size() );
	std::size_t differences = 0;
	std::size_t first = 0;

	for( std::size_t i = 0; i < limit; ++i ) {
		if( a[i] != b[i] ) {
			if( differences == 0 ) {
				first = i;
			}
			++differences;
		}
	}

	if( differences != 0 || a.size() != b.size() ) {
		std::cout << "[rfa] " << label << ": " << differences << " differing bytes in "
		          << limit << " compared, first at offset " << first << "\n";

		std::cout << "        ours   :";
		for( std::size_t i = first > 8 ? first - 8 : 0; i < std::min( first + 16, a.size() ); ++i ) {
			std::printf( " %02X", a[i] );
		}
		std::cout << "\n        oracle :";
		for( std::size_t i = first > 8 ? first - 8 : 0; i < std::min( first + 16, b.size() ); ++i ) {
			std::printf( " %02X", b[i] );
		}
		std::cout << "\n";

		return false;
	}

	return true;
}

/**
 * Structural and payload comparison, for the case where the bytes legitimately differ.
 *
 * The two archives must agree on version, entry order, names, uncompressed sizes and the
 * opaque per-entry fields, and every entry must decompress to identical bytes. That is
 * what "interchangeable" means; it does not require identical compressed streams.
 */
bool compare_archives_semantically( const std::string & ours,
                                    const std::string & theirs,
                                    const std::string & label )
{
	RfaArchive a;
	RfaArchive b;
	std::string error;

	if( !a.open( ours, &error ) ) {
		std::cout << "[rfa] " << label << ": cannot open ours: " << error << "\n";
		return false;
	}

	if( !b.open( theirs, &error ) ) {
		std::cout << "[rfa] " << label << ": cannot open the oracle: " << error << "\n";
		return false;
	}

	if( a.version() != b.version() ) {
		std::cout << "[rfa] " << label << ": version " << a.version() << " vs " << b.version() << "\n";
		return false;
	}

	if( a.entries().size() != b.entries().size() ) {
		std::cout << "[rfa] " << label << ": " << a.entries().size() << " entries vs "
		          << b.entries().size() << "\n";
		return false;
	}

	PayloadReader reader_a( ours );
	PayloadReader reader_b( theirs );

	for( std::size_t i = 0; i < a.entries().size(); ++i ) {
		const Entry & ea = a.entries()[i];
		const Entry & eb = b.entries()[i];

		if( ea.name != eb.name ) {
			std::cout << "[rfa] " << label << ": entry " << i << " is '" << ea.name
			          << "' but the oracle has '" << eb.name << "'\n";
			return false;
		}

		if( ea.uncompressed_size != eb.uncompressed_size ) {
			std::cout << "[rfa] " << label << ": " << ea.name << " uncompressedSize "
			          << ea.uncompressed_size << " vs " << eb.uncompressed_size << "\n";
			return false;
		}

		if( ea.flags != eb.flags || ea.reserved1 != eb.reserved1 || ea.reserved2 != eb.reserved2 ) {
			std::cout << "[rfa] " << label << ": " << ea.name << " opaque fields differ\n";
			return false;
		}

		std::vector<unsigned char> pa;
		std::vector<unsigned char> pb;

		if( !reader_a.read( ea, pa, &error ) || !reader_b.read( eb, pb, &error ) ) {
			std::cout << "[rfa] " << label << ": " << ea.name << " failed to decompress: "
			          << error << "\n";
			return false;
		}

		if( pa != pb ) {
			report_difference( label + " " + ea.name, pa, pb );
			return false;
		}
	}

	return true;
}

