TestCasePtr test_writer_collect_files_names_them_base_slash_relative()
{
	return std::make_shared<TestCaseFuncOneFile>(
		"writer_collect_files_names_them_base_slash_relative",
		[]( const std::string & scratch ) {
			Scratch work( scratch );
			const std::string root = make_tree( work, "menu" );

			std::vector<SourceFile> files;
			std::string error;

			if( !RfaWriter::collect_files( root, "menu", files, &error ) ) {
				std::cout << "[rfa] collect_files failed: " << error << "\n";
				return false;
			}

			std::vector<std::string> names;
			for( const SourceFile & file : files ) {
				names.push_back( file.name );

				// forward slashes only: rfaUnpack.exe -l cannot match backslashes
				if( file.name.find( '\\' ) != std::string::npos ) {
					return false;
				}
			}

			std::sort( names.begin(), names.end() );

			const std::vector<std::string> expected = {
				"menu/a.txt", "menu/blob.bin", "menu/empty.txt", "menu/nested/deep.txt"
			};

			return names == expected;
		},
		std::ios::out );
}

TestCasePtr test_writer_store_policy_writes_version_0_raw_entries()
{
	return std::make_shared<TestCaseFuncOneFile>(
		"writer_store_policy_writes_version_0_raw_entries",
		[]( const std::string & scratch ) {
			Scratch work( scratch );
			const std::string root = make_tree( work, "menu" );
			const std::string archive = work.path( "store.rfa" );

			std::string error;
			if( !build( root, "menu", archive, CompressionPolicy::Store, 1, &error ) ) {
				std::cout << "[rfa] write failed: " << error << "\n";
				return false;
			}

			RfaArchive written;
			if( !written.open( archive, &error ) ) {
				std::cout << "[rfa] cannot reopen store.rfa: " << error << "\n";
				return false;
			}

			// rfaPack.exe writes version 0 and raw entries when -Compress is absent
			if( written.version() != VERSION_0 || !written.problems().empty() ) {
				return false;
			}

			for( const Entry & entry : written.entries() ) {
				if( entry.variant != PayloadVariant::Raw ) {
					return false;
				}
				if( entry.stored_size != entry.uncompressed_size ) {
					return false;
				}
			}

			// data starts where every observed archive puts it
			return written.entries().size() == 4
			    && written.entries()[0].data_offset == DEFAULT_FIRST_DATA_OFFSET;
		},
		std::ios::out );
}

TestCasePtr test_writer_compress_policy_writes_version_1_chunked_entries()
{
	return std::make_shared<TestCaseFuncOneFile>(
		"writer_compress_policy_writes_version_1_chunked_entries",
		[]( const std::string & scratch ) {
			Scratch work( scratch );
			const std::string root = make_tree( work, "menu" );
			const std::string archive = work.path( "compress.rfa" );

			std::string error;
			if( !build( root, "menu", archive, CompressionPolicy::Compress, 1, &error ) ) {
				std::cout << "[rfa] write failed: " << error << "\n";
				return false;
			}

			RfaArchive written;
			if( !written.open( archive, &error ) ) {
				return false;
			}

			if( written.version() != VERSION_1 || !written.problems().empty() ) {
				return false;
			}

			// every entry chunked; a version-1 archive must never hold a raw non-empty
			// entry, because rfaUnpack.exe crashes trying to decompress one
			for( const Entry & entry : written.entries() ) {
				if( entry.variant != PayloadVariant::Chunked ) {
					return false;
				}
				if( entry.uncompressed_size > 0 && entry.stored_size == entry.uncompressed_size ) {
					return false;
				}
			}

			const Entry * blob = written.find( "menu/blob.bin" );

			return blob != nullptr
			    && blob->chunk_count() == chunk_count_for( blob->uncompressed_size )
			    && blob->chunk_count() == 7;
		},
		std::ios::out );
}

TestCasePtr test_writer_round_trips_a_tree_through_our_reader()
{
	return std::make_shared<TestCaseFuncOneFile>(
		"writer_round_trips_a_tree_through_our_reader",
		[]( const std::string & scratch ) {
			Scratch work( scratch );
			const std::string root = make_tree( work, "menu" );

			for( CompressionPolicy policy : { CompressionPolicy::Store, CompressionPolicy::Compress } ) {
				const std::string archive = work.path( policy == CompressionPolicy::Store
				                                     ? "rt_store.rfa" : "rt_compress.rfa" );

				std::string error;
				if( !build( root, "menu", archive, policy, 1, &error ) ) {
					return false;
				}

				RfaArchive written;
				if( !written.open( archive, &error ) || !written.problems().empty() ) {
					return false;
				}

				PayloadReader reader( archive );

				for( const Entry & entry : written.entries() ) {
					std::vector<unsigned char> payload;
					if( !reader.read( entry, payload, &error ) ) {
						std::cout << "[rfa] " << error << "\n";
						return false;
					}

					const std::string relative = entry.name.substr( std::string( "menu/" ).size() );
					const std::vector<unsigned char> expected = read_whole_file( work.path( "menu/" + relative ) );

					if( payload != expected ) {
						report_difference( entry.name, payload, expected );
						return false;
					}
				}
			}

			return true;
		},
		std::ios::out );
}

TestCasePtr test_writer_multi_chunk_entry_round_trips()
{
	return std::make_shared<TestCaseFuncOneFile>(
		"writer_multi_chunk_entry_round_trips",
		[]( const std::string & scratch ) {
			Scratch work( scratch );

			// incompressible: every chunk is larger compressed than raw, which is the
			// case most likely to expose a chunk-boundary mistake
			const std::vector<unsigned char> big = pseudo_random( 5 * 32768 + 17, 99 );
			work.write( "menu/big.bin", big );

			const std::string root = work.path( "menu" );
			const std::string archive = work.path( "multi.rfa" );

			std::string error;
			if( !build( root, "menu", archive, CompressionPolicy::Compress, 4, &error ) ) {
				return false;
			}

			RfaArchive written;
			const bool opened = written.open( archive, &error );

			if( !opened ) {
				std::cout << "[rfa] cannot open the multi-chunk archive: " << error << "\n";
				return false;
			}

			if( !written.problems().empty() ) {
				std::cout << "[rfa] multi-chunk archive reported problems:";

				for( const std::string & problem : written.problems() ) {
					std::cout << "\n        " << problem;
				}

				std::cout << "\n";
				return false;
			}

			const Entry * entry = written.find( "menu/big.bin" );

			if( entry == nullptr ) {
				std::cout << "[rfa] menu/big.bin not found in the written archive\n";
				return false;
			}

			if( entry->chunk_count() != 6 ) {
				std::cout << "[rfa] menu/big.bin has " << entry->chunk_count()
				          << " chunks, expected 6 (unc=" << entry->uncompressed_size << ")\n";
				return false;
			}

			std::vector<unsigned char> payload;
			PayloadReader reader( archive );

			if( !reader.read( *entry, payload, &error ) ) {
				std::cout << "[rfa] " << error << "\n";
				return false;
			}

			if( payload != big ) {
				report_difference( "menu/big.bin", payload, big );
				return false;
			}

			return true;
		},
		std::ios::out );
}

TestCasePtr test_writer_empty_file_round_trips_in_both_policies()
{
	return std::make_shared<TestCaseFuncOneFile>(
		"writer_empty_file_round_trips_in_both_policies",
		[]( const std::string & scratch ) {
			Scratch work( scratch );
			work.write( "menu/empty.txt", std::vector<unsigned char>() );
			work.write( "menu/other.txt", bytes( "x" ) );

			for( CompressionPolicy policy : { CompressionPolicy::Store, CompressionPolicy::Compress } ) {
				const std::string archive = work.path( policy == CompressionPolicy::Store
				                                     ? "empty_store.rfa" : "empty_compress.rfa" );

				std::string error;
				if( !build( work.path( "menu" ), "menu", archive, policy, 1, &error ) ) {
					return false;
				}

				RfaArchive written;
				if( !written.open( archive, &error ) || !written.problems().empty() ) {
					std::cout << "[rfa] empty " << ( policy == CompressionPolicy::Store ? "store" : "compress" )
					          << " archive reported problems\n";
					for( const std::string & problem : written.problems() ) {
						std::cout << "        " << problem << "\n";
					}
					return false;
				}

				const Entry * empty = written.find( "menu/empty.txt" );
				if( empty == nullptr || empty->uncompressed_size != 0 ) {
					return false;
				}

				std::vector<unsigned char> payload;
				PayloadReader reader( archive );

				if( !reader.read( *empty, payload ) || !payload.empty() ) {
					return false;
				}
			}

			return true;
		},
		std::ios::out );
}

TestCasePtr test_writer_orders_entries_like_the_oracle()
{
	// rfaPack.exe does not sort by full path: it emits each directory's own regular files
	// (sorted) before descending into its subdirectories (sorted). Entry order reaches the
	// archive table verbatim, so matching it is what makes byte-identical output possible.
	// Verified against the real tool with two nesting levels and several siblings.
	return std::make_shared<TestCaseFuncOneFile>(
		"writer_orders_entries_like_the_oracle",
		[]( const std::string & scratch ) {
			Scratch work( scratch );

			work.write( "menu/z.txt", bytes( "z" ) );
			work.write( "menu/a.txt", bytes( "a" ) );
			work.write( "menu/d1/c.txt", bytes( "c" ) );
			work.write( "menu/d1/e/f.txt", bytes( "f" ) );
			work.write( "menu/d2/b.txt", bytes( "b" ) );

			std::vector<SourceFile> files;
			std::string error;

			if( !RfaWriter::collect_files( work.path( "menu" ), "menu", files, &error ) ) {
				return false;
			}

			std::vector<std::string> names;
			for( const SourceFile & file : files ) {
				names.push_back( file.name );
			}

			// note: NOT ASCII-ascending, which would put menu/z.txt last
			const std::vector<std::string> expected = {
				"menu/a.txt", "menu/z.txt", "menu/d1/c.txt", "menu/d1/e/f.txt", "menu/d2/b.txt"
			};

			if( names != expected ) {
				std::cout << "[rfa] entry order differs from the oracle walk order:\n";
				for( const std::string & name : names ) {
					std::cout << "        got " << name << "\n";
				}
				return false;
			}

			return true;
		},
		std::ios::out );
}

TestCasePtr test_writer_is_deterministic_across_thread_counts()
{
	// Thread scheduling must not influence the output, or archives become uncomparable.
	return std::make_shared<TestCaseFuncOneFile>(
		"writer_is_deterministic_across_thread_counts",
		[]( const std::string & scratch ) {
			Scratch work( scratch );
			work.write( "menu/a.bin", pseudo_random( 200000, 7 ) );
			work.write( "menu/b.bin", pseudo_random( 150000, 8 ) );
			work.write( "menu/c.txt", bytes( "text\r\n" ) );

			std::string error;

			if( !build( work.path( "menu" ), "menu", work.path( "t1.rfa" ),
			            CompressionPolicy::Compress, 1, &error ) ) {
				return false;
			}
			if( !build( work.path( "menu" ), "menu", work.path( "t8.rfa" ),
			            CompressionPolicy::Compress, 8, &error ) ) {
				return false;
			}

			return compare_archives( work.path( "t1.rfa" ), work.path( "t8.rfa" ), "threads 1 vs 8" );
		},
		std::ios::out );
}

TestCasePtr test_writer_missing_source_leaves_no_archive()
{
	return std::make_shared<TestCaseFuncOneFile>(
		"writer_missing_source_leaves_no_archive",
		[]( const std::string & scratch ) {
			Scratch work( scratch );
			const std::string archive = work.path( "partial.rfa" );

			std::error_code ec;
			std::filesystem::remove( archive, ec );

			std::vector<SourceFile> files;
			SourceFile file;
			file.name = "menu/missing.bin";
			file.path = "definitely/not/here.bin";
			files.push_back( file );

			WriteOptions options;
			RfaWriter writer;

			std::string error;
			const bool ok = writer.write( files, archive, options, nullptr, &error );

			// a failed pack must not leave a half-written archive that looks valid
			return !ok && !error.empty() && !std::filesystem::exists( archive );
		},
		std::ios::out );
}

TestCasePtr test_writer_matches_the_golden_store_archive_byte_for_byte()
{
	// With no compression involved, our archive must be byte-identical to rfaPack.exe's.
	// This transitively pins the 148-byte reserved region, the first data offset (156),
	// the reserved entry field, the version, the table layout and the entry ORDER - so a
	// pass here is strong evidence of a true drop-in replacement.
	return std::make_shared<TestCaseFuncOneFile>(
		"writer_matches_the_golden_store_archive_byte_for_byte",
		[]( const std::string & scratch ) {
			Scratch work( scratch );
			const std::string root = golden_root();

			if( root.empty() ) {
				std::cout << "[rfa] tests/data/golden not found; run tools/rfa_golden_archives.py\n";
				return false;
			}

			const std::string ours = work.path( "ours-store.rfa" );

			std::string error;
			if( !build( root + "/tree", "menu", ours, CompressionPolicy::Store, 1, &error ) ) {
				std::cout << "[rfa] our writer failed: " << error << "\n";
				return false;
			}

			return compare_archives( ours, root + "/oracle-store.rfa", "store" );
		},
		std::ios::out );
}

TestCasePtr test_writer_compress_archive_is_interchangeable_with_the_oracle()
{
	// Deliberately NOT a byte comparison. RFA Pack 1.7 embeds a 2003-era LZO whose
	// lzo1x_1_compress picks different (equally valid) matches than the miniLZO 2.10 we
	// vendor, so the compressed streams differ while the archives stay interchangeable:
	// same entries in the same order, same sizes, same opaque fields, and every payload
	// decompresses to identical bytes.
	return std::make_shared<TestCaseFuncOneFile>(
		"writer_compress_archive_is_interchangeable_with_the_oracle",
		[]( const std::string & scratch ) {
			Scratch work( scratch );
			const std::string root = golden_root();

			if( root.empty() ) {
				std::cout << "[rfa] tests/data/golden not found; run tools/rfa_golden_archives.py\n";
				return false;
			}

			const std::string ours = work.path( "ours-compress.rfa" );

			std::string error;
			if( !build( root + "/tree", "menu", ours, CompressionPolicy::Compress, 1, &error ) ) {
				std::cout << "[rfa] our writer failed: " << error << "\n";
				return false;
			}

			return compare_archives_semantically( ours, root + "/oracle-compress.rfa", "compress" );
		},
		std::ios::out );
}
